/// A city dot with a detail tier: 0 = major (always), 1 = oblast centre
/// (zoom ≥ 1.7), 2 = town (zoom ≥ 2.8).
class MapCity {
  final String name;
  final double lon;
  final double lat;
  final int tier;
  const MapCity(this.name, this.lon, this.lat, this.tier);
}

